// Completion logic for JadenScript, kept free of the `vscode` module so the
// test suite can run it under plain node.
//
// TextMate grammars cannot answer "which blocks start with setPen", so the
// extension ships a JSON snapshot of the compiler's tables (generated by
// tools/gen_vscode_data.py) and this file turns it into completion items.

"use strict";

// CompletionItemKind values (kept as numbers so `vscode` is not required).
const KIND = {
  method: 1,
  function: 2,
  field: 4,
  variable: 5,
  class: 6,
  property: 9,
  enumMember: 19,
  keyword: 13,
  snippet: 14,
  constant: 20,
  struct: 21,
};

//: The list methods, so a `x.y.get(…)` call can prove `x.y` is a list.
const LIST_METHOD_NAMES = [
  "add", "append", "clear", "contains", "delete", "get", "indexOf",
  "insert", "length", "replace", "set", "show", "hide",
];

const KIND_NAMES = {
  keyword: KIND.keyword,
  modifier: KIND.keyword,
  type: KIND.keyword,
  literal: KIND.constant,
  reserved: KIND.enumMember,
  function: KIND.function,
  command: KIND.method,
  reporter: KIND.function,
  property: KIND.property,
  namespace: KIND.class,
  constant: KIND.constant,
  variable: KIND.variable,
  class: KIND.class,
  method: KIND.method,
};

/**
 * Describe the word being typed: everything before `offset` on the current
 * line, split into the parts completion cares about.
 */
function contextAt(text, offset) {
  const before = text.slice(0, offset);
  const lineStart = before.lastIndexOf("\n") + 1;
  const line = before.slice(lineStart);
  return {
    line,
    lineStart,
    // `Pen.setPen` -> { namespace: "Pen", prefix: "setPen" }
    member: /([A-Za-z_$][\w$]*)\s*\.\s*([\w$]*)$/.exec(line),
    // `myList.get` -> the receiver is a list, not a namespace
    word: /([A-Za-z_$][\w$]*)$/.exec(line),
    feature: /#enable_feature\s*<\s*([\w]*)$/.exec(line),
    inComment: /\/\//.test(line) && line.indexOf("//") < line.length,
    commentPrefix: /^\s*\/\/\s*([\w ]*)$/.exec(line),
    // `// costume center|` - the asset annotations the importer writes.
    assetComment: /^\s*\/\/\s*(?:costume|sound)\b[^;]*$/.exec(line),
    inString: isInsideString(line),
  };
}

function isInsideString(line) {
  let quote = null;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (quote) {
      if (ch === "\\") i++;
      else if (ch === quote) quote = null;
    } else if (ch === '"' || ch === "'") {
      quote = ch;
    }
  }
  return quote !== null;
}

const DOC = (text) => ({ kind: "markdown", value: text });

function item(label, kind, detail, doc, extra) {
  return Object.assign(
    {
      label,
      kind,
      detail,
      documentation: doc ? DOC(doc) : undefined,
      sortText: undefined,
    },
    extra || {}
  );
}

/** Strip string literals so braces and dots inside them do not confuse the scan. */
function stripStrings(line) {
  return line
    .replace(/"(?:\\.|[^"\\])*"/g, '""')
    .replace(/'(?:\\.|[^'\\])*'/g, "''");
}

const NAME = "[A-Za-z_$][\\w$]*";

/** The runtime namespace names, so `Pen.x = 1` is never read as stage state. */
function namespaceNames(data) {
  // ``namespaces`` only holds the ones with members; ``builtinNamespaces`` is
  // the compiler's full list, so an empty namespace still counts as one.
  const names = new Set(Object.keys((data && data.namespaces) || {}));
  for (const name of (data && data.builtinNamespaces) || []) names.add(name);
  return names;
}
const DOTTED = NAME + "(?:\\." + NAME + ")*";

/**
 * Everything the document declares, so completion can answer "what is this
 * receiver?" instead of guessing. Returns:
 *
 * - `classes`: name -> `{ members: Map<leaf, {list: bool, method: bool}> }`
 * - `globals`: declared name (possibly dotted, `Player.notes`) -> `{list}`
 * - `lists`:   names known to be lists (file scope and imported `.jsa`/`.jsl`)
 *
 * A `..` inside a name is not valid, so dotted names here are always the
 * `Prefix.leaf` spelling a stage variable uses.
 */
function scanDocument(text, namespaceNames) {
  const known = namespaceNames || new Set();
  const classes = new Map();
  const globals = new Map();
  const lists = new Set();
  /** @type {Array<{name: string, depth: number}>} */
  const open = [];
  let depth = 0;
  let pending = null;

  const owner = () => (open.length ? open[open.length - 1].name : null);
  const classOf = (name) => {
    if (!classes.has(name)) {
      classes.set(name, { members: new Map(), namespace: "" });
    }
    return classes.get(name);
  };
  const declare = (name, isList, isPublic) => {
    if (!name) return;
    const host = owner();
    if (host) {
      const member = name.startsWith(host + ".") ? name.slice(host.length + 1) : name;
      classOf(host).members.set(member, {
        list: isList,
        method: false,
        isPublic: isPublic !== false,
      });
      if (name.includes(".")) {
        globals.set(name, { list: isList });
        if (isList) lists.add(name);
      }
    } else {
      globals.set(name, { list: isList });
      if (isList) lists.add(name);
    }
  };

  const classRe = new RegExp("^class\\s+(" + NAME + ")");
  const methodRe = new RegExp("(?:void)\\s+(" + DOTTED + ")\\s*\\(");
  const stateRe = new RegExp(
    "(?:public|private)\\s+(?!void\\b)(" + DOTTED + ")\\s*(=)?\\s*(\\[)?"
  );
  const bareRe = new RegExp("^(?:public|private)\\s+(?!" + "void\\b)(" + DOTTED + ")\\s*;");
  const importRe = new RegExp('import\\s+"([^"]+)"(?:\\s+as\\s+(?:"([^"]+)"|(' + NAME + ")))?");
  const forRe = new RegExp("\\bfor\\s+(" + DOTTED + ")\\s+in\\b");
  const paramRe = new RegExp("\\bvoid\\s+" + DOTTED + "\\s*\\(([^)]*)\\)");
  // `Graph.force_min = 0;` declares stage state the same way `public` does.
  const dottedAssignRe = new RegExp("^(" + NAME + "(?:\\." + NAME + ")+)\\s*[+\\-*/%]?=[^=]");
  // `Graph.v1.clear()` proves `Graph.v1` is a list.
  const dottedMethodRe = new RegExp(
    "(" + NAME + "(?:\\." + NAME + ")+)\\s*\\.\\s*(" +
      LIST_METHOD_NAMES.join("|") + ")\\s*\\("
  );
  // `NpGraph: name="NpGraph", … , namespace="Graph";` names the class's prefix.
  const spriteDeclRe = new RegExp(
    "^(" + NAME + ")\\s*:\\s*[\\w\\s'\"=,.-]*?\\b(?:namespace|ns)\\s*=\\s*\"([^\"]*)\""
  );
  const spriteNamespaces = new Map();

  for (const raw of text.split("\n")) {
    const line = raw.trim();
    const clean = stripStrings(line);
    let m;

    if ((m = spriteDeclRe.exec(line))) spriteNamespaces.set(m[1], m[2]);
    if ((m = classRe.exec(line))) {
      pending = m[1];
      classOf(m[1]);
      const ns = /\b(?:namespace|ns)\s*=\s*"([^"]*)"/.exec(line);
      if (ns) classOf(m[1]).namespace = ns[1];
      else if (spriteNamespaces.has(m[1])) classOf(m[1]).namespace = spriteNamespaces.get(m[1]);
    }
    if ((m = methodRe.exec(line))) {
      const full = m[1];
      const host = owner();
      const leaf = host && full.startsWith(host + ".") ? full.slice(host.length + 1) : full;
      if (host) classOf(host).members.set(leaf, { list: false, method: true });
    }
    if ((m = stateRe.exec(line)) && m[1] !== "void") {
      declare(m[1], Boolean(m[3]), /^public\b/.test(line));
    } else if ((m = bareRe.exec(line))) {
      declare(m[1], false, /^public\b/.test(line));
    }
    if ((m = importRe.exec(line))) {
      const alias = m[2] || m[3] || m[1].split("/").pop().replace(/\.[^.]+$/, "");
      const isList = /\.(?:jsa|jsl)$/i.test(m[1]);
      declare(alias, isList);
    }
    if ((m = dottedAssignRe.exec(line))) {
      const head = m[1].split(".")[0];
      if (!known.has(head) && !m[1].includes("..")) declare(m[1], false, true);
    }
    if ((m = dottedMethodRe.exec(line))) {
      const head = m[1].split(".")[0];
      if (!known.has(head)) declare(m[1], true, true);
    }
    if ((m = forRe.exec(line))) declare(m[1], false);
    if ((m = paramRe.exec(line))) {
      for (const part of m[1].split(",")) {
        const name = part.trim();
        if (/^[A-Za-z_$][\w$]*$/.test(name)) declare(name, false);
      }
    }

    for (const ch of clean) {
      if (ch === "{") {
        depth += 1;
        if (pending) {
          open.push({ name: pending, depth });
          pending = null;
        }
      } else if (ch === "}") {
        if (open.length && open[open.length - 1].depth === depth) open.pop();
        depth = Math.max(0, depth - 1);
      }
    }
  }
  return { classes, globals, lists };
}

/** Identifiers the document already uses: classes, methods, variables, lists. */
function documentSymbols(text, data) {
  const out = new Map();
  const add = (name, kind, detail) => {
    if (!name || out.has(name)) return;
    out.set(name, { name, kind, detail });
  };
  const scan = scanDocument(text, namespaceNames(data));
  for (const name of scan.classes.keys()) add(name, "class", "class in this file");
  for (const [name, info] of scan.globals) {
    add(name, "variable", info.list ? "list in this file" : "variable in this file");
    const leaf = name.split(".").pop();
    if (leaf !== name) {
      add(leaf, "variable", info.list ? "list in this file" : "variable in this file");
    }
  }
  for (const [owner, info] of scan.classes) {
    for (const [leaf, member] of info.members) {
      add(leaf, member.method ? "method" : "variable",
        (member.method ? "method" : member.list ? "list" : "variable") + " of " + owner);
    }
  }
  return out;
}

/**
 * The completions for a caret position.
 *
 * @param {string} text whole document
 * @param {number} offset caret offset in `text`
 * @param {object} data the generated `data/jsw.json`
 * @param {object} [options] `{ locals: boolean }`
 * @returns {Array<object>} plain completion items
 */
function provideCompletions(text, offset, data, options) {
  const opts = options || {};
  const ctx = contextAt(text, offset);

  if (ctx.feature) {
    const prefix = ctx.feature[1].toLowerCase();
    return data.features
      .filter((f) => f.toLowerCase().startsWith(prefix))
      .map((f) => item(f, KIND.constant, "feature switch", `#enable_feature<${f}>;`));
  }

  // Inside a line comment: suggest the annotations the decompiler writes, and
  // otherwise stay quiet (a comment is prose).
  if (ctx.inComment) {
    if (ctx.assetComment && data.assetKeys) {
      // `// costume centerx=0 centery=0 res=1` — only the keys are useful here.
      const typedKey = (/\b([\w]+)$/.exec(ctx.line) || ["", ""])[1].toLowerCase();
      return data.assetKeys
        .filter((k) => k.label.startsWith(typedKey))
        .map((k) => item(k.label, KIND.property, "asset annotation", k.doc, {
          insertText: k.label + "=",
          filterText: k.label,
        }));
    }
    const typed = (ctx.commentPrefix ? ctx.commentPrefix[1] : "").trim().toLowerCase();
    return data.annotations
      .filter((a) => a.label.toLowerCase().startsWith(typed))
      .map((a) => item(a.label, KIND.keyword, "annotation", a.doc));
  }

  // `metadata |` — the monitor modes; `metadata list Stage.x |` — at/hidden/…
  const metadata = /^\s*metadata\s+(?:([\w]*)\s*)$/.exec(ctx.line);
  if (metadata && data.monitorModes) {
    const typed = metadata[1].toLowerCase();
    return data.monitorModes
      .filter((m) => m.label.startsWith(typed))
      .map((m) => item(m.label, KIND.constant, "monitor mode", m.doc));
  }
  // `metadata list Stage.|` — the state this project can monitor.
  const metaTarget = /^\s*metadata\s+(?:list|large|slider|normal|default)\s+([\w.]*)$/.exec(
    ctx.line
  );
  if (metaTarget) {
    const typed = metaTarget[1];
    const scan = scanDocument(text, namespaceNames(data));
    const targets = new Map();
    for (const [name, info] of scan.globals) {
      targets.set(name, info.list ? "list" : "variable");
    }
    for (const [name, info] of scan.classes) {
      for (const [leaf, member] of info.members) {
        if (member.method) continue;
        if (member.isPublic !== false) {
          // A member may already be written with its prefix (`Graph.dpoint_x`
          // inside `class NpGraph` with `namespace="Graph"`).
          const global =
            info.namespace && !leaf.startsWith(info.namespace + ".")
              ? info.namespace + "." + leaf
              : leaf;
          targets.set("Stage." + global, member.list ? "list" : "variable");
        }
        targets.set(name + "." + leaf, member.list ? "list" : "variable");
      }
    }
    return [...targets]
      .filter(([label]) => label.startsWith(typed) || label.startsWith("Stage." + typed))
      .map(([label, detail]) => item(label, KIND.variable, detail, ""))
      .sort((a, b) => a.label.localeCompare(b.label));
  }

  const metadataTail = /^\s*metadata\s+[\w.]+\s+[\w.]+\s+([\w]*)$/.exec(ctx.line)
    || /^\s*metadata\s+[\w.]+\s+([\w]*)$/.exec(ctx.line);
  if (metadataTail && data.metadataWords) {
    const typed = metadataTail[1].toLowerCase();
    return data.metadataWords
      .filter((w) => w.label.startsWith(typed))
      .map((w) => item(w.label, KIND.keyword, "metadata", w.doc));
  }

  // `stage: |` / `Sprite: |` — the target's property keys, with the `=` ready.
  const target = /^\s*[A-Za-z_$][\w$]*\s*:\s*([\w]*)$/.exec(ctx.line);
  if (target && data.targetKeys) {
    const typed = target[1].toLowerCase();
    return data.targetKeys
      .filter((k) => k.label.toLowerCase().startsWith(typed))
      .map((k) => item(k.label, KIND.keyword, "target property", k.doc, {
        sortText: "0" + k.label,
        insertText: k.label + "=",
        filterText: k.label,
      }));
  }

  if (ctx.inString) {
    // Inside a key block's quotes, offer the names the VM actually reports.
    if (/\b(?:is)?[Kk]eyPressed\s*\(\s*["'][^"']*$/.test(ctx.line)) {
      const typed = (/["']([^"']*)$/.exec(ctx.line) || ["", ""])[1].toLowerCase();
      return (data.keyNames || [])
        .filter((k) => k.label.startsWith(typed))
        .map((k) => item(k.label, KIND.enumMember, k.detail, k.doc));
    }
    return [];
  }

  if (ctx.member) {
    const [, receiver, prefix] = ctx.member;
    const members = new Map();
    // Hats are written as methods; the snippet beats the bare name, so the
    // plain member with the same leaf is dropped below.
    const hatLeaves = new Map();
    for (const hat of data.hats || []) {
      const dot = hat.label.indexOf(".");
      if (dot > 0 && hat.label.slice(0, dot) === receiver) {
        hatLeaves.set(hat.label.slice(dot + 1), hat);
      }
    }
    const namespace = data.namespaces[receiver];
    if (namespace) {
      for (const [name, info] of namespace.members) {
        if (!hatLeaves.has(name)) members.set(name, info);
      }
      if (receiver === "microbit") {
        // The menu values are written as constants: `microbit.buttonA`.
        for (const constant of data.microbitConstants || []) {
          members.set(constant.label, {
            kind: "constant",
            detail: `"${constant.value}"`,
            doc: "micro:bit menu value",
          });
        }
      }
    } else if (namespaceNames(data).has(receiver)) {
      // A namespace with no blocks to offer: say nothing. Guessing "list"
      // here is how `Variables.` used to show `add(item)`.
    } else {
      // The receiver is not a runtime namespace, so ask the document what it
      // is instead of assuming "list" and offering `add`/`get` for everything.
      const scan = scanDocument(text, namespaceNames(data));
      const asClass = scan.classes.get(receiver);
      const prefixed = [...scan.globals].filter(([name]) => name.startsWith(receiver + "."));

      if (asClass) {
        // `Lyrics.` — this file's class: its state (and, below, its methods).
        for (const [leaf, member] of asClass.members) {
          members.set(leaf, {
            kind: member.method ? "command" : "variable",
            detail: member.method
              ? "method of " + receiver
              : member.list ? "list of " + receiver : "variable of " + receiver,
            doc: "",
            label: leaf,
          });
        }
      } else if (prefixed.length) {
        // `Player.` — a prefix of dotted stage state (`Player.notes`), offered
        // one path segment at a time so `Stage.` reaches `Stage.Graph.max`.
        for (const [name, info] of prefixed) {
          const leaf = name.slice(receiver.length + 1);
          const dot = leaf.indexOf(".");
          const segment = dot === -1 ? leaf : leaf.slice(0, dot);
          const deeper = dot !== -1;
          if (members.has(segment)) continue;
          members.set(segment, {
            kind: "variable",
            detail: deeper ? "namespace of state" : info.list ? "list" : "variable",
            doc: "",
          });
        }
      } else {
        // A bare name: only offer list methods when it really is a list. The
        // leaf of a dotted import counts too — `Player.NotesActive` is written
        // `NotesActive.get(i)` just as often as `Player.NotesActive.get(i)`.
        let isList = scan.lists.has(receiver);
        for (const name of scan.lists) {
          if (name === receiver || name.endsWith("." + receiver)) isList = true;
        }
        const bare = scan.globals.get(receiver);
        if (bare && bare.list) isList = true;
        for (const info of scan.classes.values()) {
          const member = info.members.get(receiver);
          if (member && member.list) isList = true;
        }
        if (isList) {
          for (const method of data.listMethods) members.set(method.label, method);
        }
      }
    }
    const lower = prefix.toLowerCase();
    const hits = [];
    for (const [name, info] of members) {
      if (!name.toLowerCase().startsWith(lower)) continue;
      hits.push(
        item(
          name,
          KIND_NAMES[info.kind] || KIND.method,
          info.detail,
          info.doc,
          { insertText: name, filterText: name }
        )
      );
    }
    for (const [leaf, hat] of hatLeaves) {
      if (!leaf.toLowerCase().startsWith(lower)) continue;
      hits.push(
        item(leaf, KIND.snippet, "hat — " + hat.detail, hat.doc, {
          sortText: "0" + leaf,
          insertText: hatSnippet(hat.label),
        })
      );
    }
    hits.sort((a, b) => a.label.localeCompare(b.label));
    return hits;
  }

  const prefix = ctx.word ? ctx.word[1] : "";
  const lower = prefix.toLowerCase();
  const starts = (label) => label.toLowerCase().startsWith(lower);
  const out = [];

  for (const kw of data.keywords) {
    if (!starts(kw.label)) continue;
    // Reserved words compile to an error, so they go below everything real.
    const rank = kw.kind === "reserved" ? "9" : "0";
    out.push(
      item(kw.label, KIND_NAMES[kw.kind] || KIND.keyword, kw.detail, kw.doc, {
        sortText: rank + kw.label,
      })
    );
  }
  for (const fn of data.builtins) {
    if (!starts(fn.label)) continue;
    out.push(item(fn.label, KIND.function, fn.detail, fn.doc, { sortText: "1" + fn.label }));
  }
  for (const name of Object.keys(data.namespaces)) {
    if (!starts(name)) continue;
    out.push(
      item(name, KIND.class, "namespace", `${name}.…`, {
        sortText: "2" + name,
        // `Pen.` is almost always what follows.
        insertText: name + ".",
      })
    );
  }
  for (const hat of data.hats || []) {
    if (!starts(hat.label)) continue;
    out.push(
      item(hat.label, KIND.snippet, hat.detail, hat.doc, {
        sortText: "1" + hat.label,
        insertText: hatSnippet(hat.label),
      })
    );
  }
  if (opts.locals !== false) {
    for (const symbol of documentSymbols(text, data).values()) {
      if (!starts(symbol.name) || symbol.name === prefix) continue;
      out.push(
        item(symbol.name, KIND_NAMES[symbol.kind] || KIND.variable, symbol.detail, undefined, {
          sortText: "3" + symbol.name,
        })
      );
    }
  }
  return out;
}

/** The `public void … { }` wrapper a hat needs, as a snippet. */
function hatSnippet(label) {
  const hook = {
    greenFlag: "// hook: green flag",
    whenClicked: "// hook: click",
    whenStageClicked: "// hook: stage click",
    whenBackdropChanges: "// hook: backdrop backdrop1",
    onSave: "// hook: before project save",
    "Events.keyPressed": "// hook: when [space] key pressed",
    "microbit.buttonPressed": "// hook: when [A] button pressed",
    "microbit.gesture": "// hook: when [moved]",
    "microbit.tilted": "// hook: when tilted [front]",
    "microbit.pinConnected": "// hook: when pin [0] connected",
  }[label];
  const signature = label === "Events.keyPressed" ? "Events.keyPressed(k)" : label + "()";
  const head = `public void ${signature} {` + (hook ? " " + hook : "");
  return { value: head + "\n    $0\n}", isSnippet: true };
}

/** Hover text for the identifier under the caret. */
function provideHover(text, offset, data) {
  const word = wordAt(text, offset);
  if (!word) return null;
  const { value, start, end } = word;

  // `Pen.setPenSize` — prefer the member when a namespace precedes it.
  const before = text.slice(0, start);
  const receiver = /([A-Za-z_$][\w$]*)\s*\.\s*$/.exec(before);
  if (receiver && data.namespaces[receiver[1]]) {
    for (const [name, info] of data.namespaces[receiver[1]].members) {
      if (name === value) {
        return range(start, end, `${receiver[1]}.${value}\n\n${info.detail}\n\n\`${info.doc}\``);
      }
    }
  }
  for (const kw of data.keywords) {
    if (kw.label === value) return range(start, end, `**${kw.label}** — ${kw.doc || kw.detail}`);
  }
  for (const fn of data.builtins) {
    if (fn.label === value) return range(start, end, `**${value}** — ${fn.doc}`);
  }
  if (data.namespaces[value]) return range(start, end, `**${value}** — runtime namespace`);
  for (const method of data.listMethods) {
    if (method.label === value) return range(start, end, `**list.${value}()** — ${method.doc}`);
  }
  return null;
}

function wordAt(text, offset) {
  const isWord = (ch) => /[\w$]/.test(ch);
  let start = offset;
  let end = offset;
  while (start > 0 && isWord(text[start - 1])) start--;
  while (end < text.length && isWord(text[end])) end++;
  if (start === end) return null;
  return { value: text.slice(start, end), start, end };
}

function range(start, end, markdown) {
  return { start, end, contents: DOC(markdown) };
}

module.exports = { provideCompletions, provideHover, contextAt, documentSymbols, KIND, KIND_NAMES };
